/*
 * A070734  Order of the subgroup of the symmetric group S_n generated by the
 *          cycles (1,2,3) and (1,2,3,...,n).
 * https://oeis.org/A070734
 *
 * Offset:    3    (a(3) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = n! for even n, n!/2 for odd n (n ≥ 3)
 * Range:     u8 n <= 5, u16 n <= 8, u32 n <= 12, u64 n <= 20, u128 n <= 20,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    if (n < 3)
        return 0;  /* no defined value below the offset */

    seq_t fact = 1;
    for (idx_t i = 2; i <= n; ++i)
        fact *= (seq_t)i;

    if ((n & 1) == 1)  /* odd n */
        fact /= 2;

    return fact;
}
